PRAGMA foreign_keys = ON;
CREATE TABLE owners (id TEXT PRIMARY KEY,issuer TEXT NOT NULL,subject TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(issuer,subject));
CREATE TABLE api_usage (owner_id TEXT NOT NULL,lane TEXT NOT NULL,window_minute INTEGER NOT NULL,requests INTEGER NOT NULL,PRIMARY KEY(owner_id,lane),FOREIGN KEY(owner_id) REFERENCES owners(id) ON DELETE CASCADE);
CREATE TABLE conversations (owner_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,turn_token TEXT,turn_expires_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id) REFERENCES owners(id) ON DELETE CASCADE);
CREATE TABLE messages (owner_id TEXT NOT NULL,id TEXT NOT NULL,conversation_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('user','assistant')),content TEXT NOT NULL,context_key TEXT NOT NULL DEFAULT '',turn_revision INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id,conversation_id) REFERENCES conversations(owner_id,id) ON DELETE CASCADE);
CREATE INDEX messages_conversation ON messages(owner_id,conversation_id,turn_revision,role);
CREATE TABLE memories (owner_id TEXT NOT NULL,id TEXT NOT NULL,content TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('preference','instruction')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id) REFERENCES owners(id) ON DELETE CASCADE);
CREATE TABLE notes (owner_id TEXT NOT NULL,id TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id) REFERENCES owners(id) ON DELETE CASCADE);
CREATE TABLE tasks (owner_id TEXT NOT NULL,id TEXT NOT NULL,cadence TEXT NOT NULL DEFAULT 'daily',time TEXT NOT NULL,timezone TEXT NOT NULL,quantity INTEGER NOT NULL,topic TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,delivery_requested INTEGER NOT NULL DEFAULT 1,schedule_revision INTEGER NOT NULL DEFAULT 1,next_run_at TEXT,mutation_token TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id) REFERENCES owners(id) ON DELETE CASCADE);
CREATE INDEX tasks_due ON tasks(enabled,next_run_at,owner_id,id);
CREATE TABLE proposals (owner_id TEXT NOT NULL,id TEXT NOT NULL,draft_json TEXT NOT NULL,expires_at TEXT NOT NULL,request_key TEXT,confirmed_task_id TEXT,created_at TEXT NOT NULL,PRIMARY KEY(owner_id,id),UNIQUE(owner_id,request_key),FOREIGN KEY(owner_id) REFERENCES owners(id) ON DELETE CASCADE,FOREIGN KEY(owner_id,confirmed_task_id) REFERENCES tasks(owner_id,id));
CREATE TABLE executions (owner_id TEXT NOT NULL,id TEXT NOT NULL,task_id TEXT NOT NULL,occurrence_key TEXT NOT NULL,scheduled_for TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempt INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 3,available_at TEXT NOT NULL,lease_until TEXT,claim_token TEXT,schedule_revision INTEGER NOT NULL,snapshot_json TEXT NOT NULL,result_json TEXT,failure TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,id),UNIQUE(owner_id,occurrence_key),FOREIGN KEY(owner_id,task_id) REFERENCES tasks(owner_id,id) ON DELETE CASCADE);
CREATE INDEX executions_ready ON executions(status,available_at,owner_id,id);
CREATE INDEX executions_history ON executions(owner_id,status,created_at,id);
CREATE TABLE execution_events (owner_id TEXT NOT NULL,id TEXT NOT NULL,execution_id TEXT NOT NULL,type TEXT NOT NULL,at TEXT NOT NULL,detail TEXT,PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id,execution_id) REFERENCES executions(owner_id,id) ON DELETE CASCADE);
CREATE INDEX execution_events_order ON execution_events(owner_id,execution_id,at,id);
